macro_rules! UncheckedAdvice {
    () => {
        # [doc = " Values supported by [`Mmap::unchecked_advise`][crate::Mmap::unchecked_advise] and [`MmapMut::unchecked_advise`][crate::MmapMut::unchecked_advise] functions."] # [doc = ""] # [doc = " These flags can be passed to the [madvise (2)][man_page] system call"] # [doc = " and effects on the mapped pages which are conceptually writes,"] # [doc = " i.e. the change the observable contents of these pages which"] # [doc = " implies undefined behaviour if the mapping is still borrowed."] # [doc = ""] # [doc = " Hence, these potentially unsafe flags must be used with the unsafe"] # [doc = " methods and the programmer has to justify that the code"] # [doc = " does not keep any borrows of the mapping active while the mapped pages"] # [doc = " are updated by the kernel's memory management subsystem."] # [doc = ""] # [doc = " [man_page]: https://man7.org/linux/man-pages/man2/madvise.2.html"] # [repr (i32)] # [derive (Clone , Copy , Debug , Eq , PartialEq , Hash)] pub enum UncheckedAdvice { # [doc = " **MADV_DONTNEED**"] # [doc = ""] # [doc = " Do not expect access in the near future.  (For the time"] # [doc = " being, the application is finished with the given range,"] # [doc = " so the kernel can free resources associated with it.)"] # [doc = ""] # [doc = " After a successful MADV_DONTNEED operation, the semantics"] # [doc = " of memory access in the specified region are changed:"] # [doc = " subsequent accesses of pages in the range will succeed,"] # [doc = " but will result in either repopulating the memory contents"] # [doc = " from the up-to-date contents of the underlying mapped file"] # [doc = " (for shared file mappings, shared anonymous mappings, and"] # [doc = " shmem-based techniques such as System V shared memory"] # [doc = " segments) or zero-fill-on-demand pages for anonymous"] # [doc = " private mappings."] # [doc = ""] # [doc = " Note that, when applied to shared mappings, MADV_DONTNEED"] # [doc = " might not lead to immediate freeing of the pages in the"] # [doc = " range.  The kernel is free to delay freeing the pages"] # [doc = " until an appropriate moment.  The resident set size (RSS)"] # [doc = " of the calling process will be immediately reduced"] # [doc = " however."] # [doc = ""] # [doc = " **MADV_DONTNEED** cannot be applied to locked pages, Huge TLB"] # [doc = " pages, or VM_PFNMAP pages.  (Pages marked with the kernel-"] # [doc = " internal VM_PFNMAP flag are special memory areas that are"] # [doc = " not managed by the virtual memory subsystem.  Such pages"] # [doc = " are typically created by device drivers that map the pages"] # [doc = " into user space.)"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Using the returned value with conceptually write to the"] # [doc = " mapped pages, i.e. borrowing the mapping when the pages"] # [doc = " are freed results in undefined behaviour."] DontNeed = libc :: MADV_DONTNEED , # [doc = " **MADV_FREE** - Linux (since Linux 4.5) and Darwin"] # [doc = ""] # [doc = " The application no longer requires the pages in the range"] # [doc = " specified by addr and len.  The kernel can thus free these"] # [doc = " pages, but the freeing could be delayed until memory"] # [doc = " pressure occurs.  For each of the pages that has been"] # [doc = " marked to be freed but has not yet been freed, the free"] # [doc = " operation will be canceled if the caller writes into the"] # [doc = " page.  After a successful MADV_FREE operation, any stale"] # [doc = " data (i.e., dirty, unwritten pages) will be lost when the"] # [doc = " kernel frees the pages.  However, subsequent writes to"] # [doc = " pages in the range will succeed and then kernel cannot"] # [doc = " free those dirtied pages, so that the caller can always"] # [doc = " see just written data.  If there is no subsequent write,"] # [doc = " the kernel can free the pages at any time.  Once pages in"] # [doc = " the range have been freed, the caller will see zero-fill-"] # [doc = " on-demand pages upon subsequent page references."] # [doc = ""] # [doc = " The MADV_FREE operation can be applied only to private"] # [doc = " anonymous pages (see mmap(2)).  In Linux before version"] # [doc = " 4.12, when freeing pages on a swapless system, the pages"] # [doc = " in the given range are freed instantly, regardless of"] # [doc = " memory pressure."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Using the returned value with conceptually write to the"] # [doc = " mapped pages, i.e. borrowing the mapping while the pages"] # [doc = " are still being freed results in undefined behaviour."] # [cfg (any (target_os = "linux" , target_vendor = "apple"))] Free = libc :: MADV_FREE , # [doc = " **MADV_REMOVE** - Linux only (since Linux 2.6.16)"] # [doc = ""] # [doc = " Free up a given range of pages and its associated backing"] # [doc = " store.  This is equivalent to punching a hole in the"] # [doc = " corresponding byte range of the backing store (see"] # [doc = " fallocate(2)).  Subsequent accesses in the specified"] # [doc = " address range will see bytes containing zero."] # [doc = ""] # [doc = " The specified address range must be mapped shared and"] # [doc = " writable.  This flag cannot be applied to locked pages,"] # [doc = " Huge TLB pages, or VM_PFNMAP pages."] # [doc = ""] # [doc = " In the initial implementation, only tmpfs(5) was supported"] # [doc = " **MADV_REMOVE**; but since Linux 3.5, any filesystem which"] # [doc = " supports the fallocate(2) FALLOC_FL_PUNCH_HOLE mode also"] # [doc = " supports MADV_REMOVE.  Hugetlbfs fails with the error"] # [doc = " EINVAL and other filesystems fail with the error"] # [doc = " EOPNOTSUPP."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Using the returned value with conceptually write to the"] # [doc = " mapped pages, i.e. borrowing the mapping when the pages"] # [doc = " are freed results in undefined behaviour."] # [cfg (target_os = "linux")] Remove = libc :: MADV_REMOVE , # [doc = " **MADV_FREE_REUSABLE** - Darwin only"] # [doc = ""] # [doc = " Behaves like **MADV_FREE**, but the freed pages are accounted for in the RSS of the process."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Using the returned value with conceptually write to the"] # [doc = " mapped pages, i.e. borrowing the mapping while the pages"] # [doc = " are still being freed results in undefined behaviour."] # [cfg (target_vendor = "apple")] FreeReusable = libc :: MADV_FREE_REUSABLE , # [doc = " **MADV_FREE_REUSE** - Darwin only"] # [doc = ""] # [doc = " Marks a memory region previously freed by **MADV_FREE_REUSABLE** as non-reusable, accounts"] # [doc = " for the pages in the RSS of the process. Pages that have been freed will be replaced by"] # [doc = " zero-filled pages on demand, other pages will be left as is."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Using the returned value with conceptually write to the"] # [doc = " mapped pages, i.e. borrowing the mapping while the pages"] # [doc = " are still being freed results in undefined behaviour."] # [cfg (target_vendor = "apple")] FreeReuse = libc :: MADV_FREE_REUSE , }
    };
}

UncheckedAdvice!()